const fs=require('fs'),puppeteer=require('puppeteer');(async()=>{const b=await puppeteer.launch({headless:true});const p=await b.newPage();const out='test-results/review-20260915';fs.mkdirSync(out,{recursive:true});const rows=[];let errs=[];p.on('pageerror',e=>errs.push(e.message));p.on('console',m=>{if(m.type()==='error')errs.push(m.text())});await p.evaluateOnNewDocument(()=>{localStorage.setItem('kv_username','TEST_REVIEW');localStorage.setItem('ketoan-settings',JSON.stringify({state:{geminiApiKey:''},version:0}));});try{for(const route of ['','thu-vien','tra-cuu','tai-khoan','bieu-mau','tien-ich','so-sanh','kiem-tra-thue','hoi-dap-ai','so-tay','huong-dan','cai-dat']){errs=[];await p.goto('https://bombeodeptrai.github.io/Tra-cuu-ke-toan-kieu-viet/#/'+route,{waitUntil:'networkidle2'});const d=await p.$('[role=dialog]');if(d){const i=await d.$('input');if(i)await i.type('TEST_REVIEW');await p.evaluate(()=>document.querySelector('[role=dialog] button[type=submit]')?.click());}const text=await p.$eval('body',e=>e.innerText);fs.writeFileSync(out+'/'+(route||'home')+'.txt',text);rows.push({route,chars:text.length,errors:[...errs],headings:await p.$$eval('h1,h2,h3',els=>els.map(e=>e.textContent))});}await p.goto('https://bombeodeptrai.github.io/Tra-cuu-ke-toan-kieu-viet/#/kiem-tra-thue',{waitUntil:'networkidle2'});const tabs=await p.$$('[role=tab]');for(let i=0;i<tabs.length;i++){await tabs[i].click();await new Promise(r=>setTimeout(r,350));fs.writeFileSync(out+'/tax-tab-'+i+'.txt',await p.$eval('body',e=>e.innerText));}await p.screenshot({path:out+'/tax.png',fullPage:true});fs.writeFileSync(out+'/routes.json',JSON.stringify(rows,null,2));console.log(JSON.stringify(rows));}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1});
